/**
 * Network demos (real OS processes talking over loopback TCP/HTTP):
 *  - netClusterBench: control plane serves the signed policy over HTTP through a
 *    lossy, delayed proxy to 3 node processes; propagation is measured on the
 *    control plane's clock; then the link is cut (partition) and healed.
 *  - netMessagingDemo: alice (this process) and bob (a separate process) run the
 *    hybrid handshake over TCP; wire replay, tampering and oversized frames are refused.
 */

const here = dirname(fileURLToPath(import.meta.url));
const ext = import.meta.url.endsWith(".ts") ? ".ts" : ".js";
const script = (rel        ) => join(here, "..", `${rel}${ext}`);
const sleep = (ms        ) => new Promise((r) => setTimeout(r, ms));

function stats(xs          ) {
  const s = [...xs].sort((a, b) => a - b);
  return { samples: s.length, median: s[Math.floor(s.length / 2)] ?? null, p95: s[Math.min(s.length - 1, Math.floor(s.length * 0.95))] ?? null, max: s.at(-1) ?? null };
}

export async function netClusterBench(opts                                                                             = {}) {
  const changes = opts.changes ?? 10;
  const dropRate = opts.dropRate ?? 0.2;
  const delayMs = opts.delayMs ?? 10;
  const pollMs = opts.pollMs ?? 50;
  const base = mkdtempSync(join(tmpdir(), "tbv-net-"));
  const cp = ControlPlane.create(join(base, "control"));
  cp.enrolDevice("maya", "maya-phone", generateSigningKeyPair().publicKey);
  const server = await servePolicy(cp.paths.dir);
  const proxy = await faultProxy(server.port);
  proxy.set({ dropRate, delayMs });
  const names = ["node-a", "node-b", "node-c"];
  const children                 = [];
  const url = `http://127.0.0.1:${proxy.port}/policy`;
  for (const n of names) {
    cp.provision(join(base, n));
    children.push(spawn(process.execPath, [script("cluster/nodeProcess"), n, join(base, n), url, String(pollMs)], { stdio: "ignore" }));
  }
  const seen = (node        , epoch        ) => server.acks.get(node)?.get(epoch);
  const waitAll = async (epoch        , limitMs        ) => {
    const until = Date.now() + limitMs;
    while (Date.now() < until && !names.every((n) => seen(n, epoch) !== undefined)) await sleep(5);
    return names.every((n) => seen(n, epoch) !== undefined);
  };
  try {
    if (!(await waitAll(cp.policy.epoch, 15_000))) throw new Error("nodes did not start");
    const propagation           = [];
    for (let i = 0; i < changes; i++) {
      const at = Date.now();
      const epoch = i === 0 ? cp.revokeDevice("maya-phone", at) : cp.enrolDevice("maya", `maya-device-${i}`, generateSigningKeyPair().publicKey, at);
      if (!(await waitAll(epoch, 10_000))) throw new Error("nodes did not converge");
      propagation.push(Math.max(...names.map((n) => (seen(n, epoch) ?? at) - at)));
    }

    // Partition: nodes cannot reach the control plane; they keep their last verified policy.
    proxy.set({ partitioned: true });
    const cutEpoch = cp.revokeActor("maya");
    await sleep(600);
    const adoptedDuringPartition = names.filter((n) => seen(n, cutEpoch) !== undefined).length;
    const healedAt = Date.now();
    proxy.set({ partitioned: false });
    const healed = await waitAll(cutEpoch, 10_000);
    const catchUp = Math.max(...names.map((n) => (seen(n, cutEpoch) ?? healedAt) - healedAt));
    return {
      transport: `HTTP (node:http) through a proxy dropping ${Math.round(dropRate * 100)}% of requests and adding ${delayMs} ms`,
      clock: "control-plane clock only (each node reports its epoch on every poll)",
      nodes: names.length,
      poll_ms: pollMs,
      policy_changes: changes,
      propagation_ms: stats(propagation),
      partition: { nodes_that_adopted_while_cut_off: adoptedDuringPartition, healed, catch_up_ms: catchUp },
    };
  } finally {
    for (const n of names) writeFileSync(join(base, n, "stop"), "");
    for (const c of children) c.kill();
    await proxy.close();
    await server.close();
  }
}

export async function netMessagingDemo(text = "Can you review the Q3 design doc?") {
  const exchange = mkdtempSync(join(tmpdir(), "tbv-msg-"));
  const alice = newIdentity("alice");
  writeFileSync(join(exchange, "alice.pub"), alice.keys.publicKey.toString("base64"));
  const bob = spawn(process.execPath, [script("messaging/peerProcess"), "bob", exchange, "alice"], { stdio: ["pipe", "pipe", "ignore"] });
  try {
    const lines = createInterface({ input: bob.stdout  });
    const port = await new Promise        ((resolve, reject) => {
      const t = setTimeout(() => reject(new Error("peer did not start")), 10_000);
      lines.on("line", (l) => {
        if (l.startsWith("ready ")) {
          clearTimeout(t);
          resolve(Number(l.slice(6)));
        }
      });
    });
    const dir            = new Map([["bob", Buffer.from(readFileSync(join(exchange, "bob.pub"), "utf8"), "base64")]]);
    const client = await connectMessaging(alice, "bob", port, dir);
    const sent = await client.sendText(text.slice(0, 200), 16);
    const first           = sent.envelopes[0];
    const attacks                                                         = [];
    const show = (r                                                    ) => (r.type === "result" ? `${r.status}${r.reason ? `: ${r.reason}` : ""}` : `${r.type}: ${r.reason ?? ""}`);
    const replay = await client.sendRaw(first);
    attacks.push({ name: "Replay a recorded frame on the wire", blocked: replay.type === "result" && replay.status === "rejected", evidence: show(replay) });
    const tampered = client.session.send(Buffer.from("pay mallory", "utf8"))[0];
    const flipped = { ...tampered, c: Buffer.from(tampered.c, "base64").map((b, i) => (i === 0 ? b ^ 1 : b)).toString("base64") };
    const tamper = await client.sendRaw(flipped);
    attacks.push({ name: "Flip one ciphertext bit in transit", blocked: tamper.type === "result" && tamper.status === "rejected", evidence: show(tamper) });
    const big = await client.sendRaw(null, "x".repeat(70 * 1024));
    attacks.push({ name: "Send an oversized frame (70 KB)", blocked: big.type === "error" && big.reason === "frame_too_large", evidence: show(big) });
    client.close();
    return {
      transport: "TCP (node:net), newline-delimited JSON frames, 64 KB limit; bob runs in a separate OS process",
      handshake: "X25519 + ML-KEM-768 → HKDF-SHA-256, transcript signed with ML-DSA-65",
      delivered: sent.results.filter((r) => r.type === "result" && r.status === "delivered").length === 1,
      chunks: sent.envelopes.length,
      attacks,
    };
  } finally {
    bob.stdin?.end();
    bob.kill();
  }
}
